  lines.forEach(l => { const h = (l.size || 10) + (l.gap || 6); if (y - h < 50) { pages.push(cur); cur = []; y = 800; } y -= h; cur.push('BT /' + (l.bold ? 'F2' : 'F1') + ' ' + (l.size || 10) + ' Tf ' + (l.rgb || '0.12 0.11 0.11') + ' rg ' + (l.x || 50) + ' ' + y + ' Td (' + esc(l.t) + ') Tj ET'); });
  pages.push(cur);
  const objs = []; const n = pages.length;
  objs[1] = '<< /Type /Catalog /Pages 2 0 R >>';
  objs[2] = '<< /Type /Pages /Count ' + n + ' /Kids [' + pages.map((p, i) => (5 + i * 2) + ' 0 R').join(' ') + '] >>';
  objs[3] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
  objs[4] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
  pages.forEach((p, i) => { const body = p.join('\n'); objs[5 + i * 2] = '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ' + (6 + i * 2) + ' 0 R >>'; objs[6 + i * 2] = '<< /Length ' + body.length + ' >>\nstream\n' + body + '\nendstream'; });
